package markup

import "github.com/microcosm-cc/bluemonday"

// Policy returns the sanitizer for one trust level. Every fragment that
// Render produces, and every fragment that a plain content write stores, goes
// through it.
//
// Contract: strict (author) and rich (admin, editor) both reject script, on*
// attributes, javascript: and data: URLs, style, iframe (embeds and widgets
// are generated by the server), form, svg, math, base, meta, object and embed.
// rich additionally allows the allow-listed elements inside ```html blocks.
// id and name are stripped inside html blocks in both levels.
//
// Stub: returns the comment policy shape for every trust level. It keeps only
// basic text elements and http, https, mailto and relative links, and adds
// rel="nofollow ugc" to links. G0 branches on trust and adds the rest.
func Policy(trust string) *bluemonday.Policy {
	_ = trust
	p := bluemonday.StrictPolicy()
	p.AllowElements("p", "br", "strong", "em", "code", "pre", "blockquote", "ul", "ol", "li")
	p.AllowElements("a")
	p.AllowAttrs("href").OnElements("a")
	p.AllowStandardURLs()
	p.RequireNoFollowOnLinks(true)
	return p
}
